using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using POS.Server.Data;using POS.Shared.DTOs;
namespace POS.Server.Controllers;
[ApiController,Route("api/traceability/lots"),Authorize(Roles="Administrador,Almacén,Producción,Gerencia")]public class TraceabilityController(AppDbContext db):ControllerBase
{
 [HttpGet("{code}")]public async Task<ActionResult<LotTraceabilityResponse>>Get(string code){var x=await db.ProductionLots.AsNoTracking().Include(x=>x.Product).Include(x=>x.User).Include(x=>x.Details).ThenInclude(x=>x.RawMaterial).FirstOrDefaultAsync(x=>x.Code==code);if(x is null)return NotFound();var moves=await db.InventoryMovements.AsNoTracking().Include(m=>m.Product).Include(m=>m.User).Where(m=>m.Reference=="LOTE:"+x.Code).OrderByDescending(m=>m.Date).Select(m=>new InventoryMovementResponse{Id=m.Id,ProductId=m.ProductId,ProductName=m.Product!.Name,UserId=m.UserId,Username=m.User!.Username,MovementType=m.MovementType,Quantity=m.Quantity,Date=m.Date,Reference=m.Reference}).ToListAsync();return Ok(new LotTraceabilityResponse{Lot=new(){Id=x.Id,ProductId=x.ProductId,ProductName=x.Product!.Name,ProductUnitOfMeasure=x.Product.UnitOfMeasure,UserId=x.UserId,Username=x.User!.Username,Code=x.Code,StartDate=x.StartDate,EndDate=x.EndDate,PlannedQuantity=x.PlannedQuantity,ProducedQuantity=x.ProducedQuantity,Status=x.Status,Materials=x.Details.Select(d=>new ProductionLotMaterialResponse{Id=d.Id,RawMaterialId=d.RawMaterialId,RawMaterialName=d.RawMaterial!.Name,UnitOfMeasure=d.RawMaterial.UnitOfMeasure,QuantityUsed=d.QuantityUsed}).ToList()},Movements=moves});}
}
